def variants(shape):
 ss=set(shape); vs=[]
 for k in range(4):
  for flip in [False,True]:
   pts=set()
   for r,c in ss:
    if flip:c=-c
    for _ in range(k):r,c=c,-r
    pts.add((r,c))
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   pts=frozenset((r-mr,c-mc) for r,c in pts)
   if pts not in vs:vs.append(pts)
 return vs
def matches(arr,shape,require_bg=True):
