 for sh in variants(shape):
  hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
  for r0 in range(H-hh+1):
   for c0 in range(W-ww+1):
    ok=True
    for rr in range(hh):
     for cc in range(ww):
      want=0 if (rr,cc) in sh else 6
      if require_bg and arr[r0+rr][c0+cc]!=want:ok=False
      elif not require_bg and (rr,cc) in sh and arr[r0+rr][c0+cc]!=0:ok=False
    if ok:
